const updateTFTRunState = `-- name: UpdateTFTRunState :exec
UPDATE tft_crawl_runs
SET status = $1,
    desired_state = $2,
    stage = $3,
    last_error = $4,
    started_at = CASE WHEN $1::text = 'running' THEN COALESCE(started_at, now()) ELSE started_at END,
    ended_at = CASE WHEN $1::text IN ('completed','completed_with_errors','cancelled','failed') THEN now() ELSE NULL END,
    updated_at = now()
WHERE id = $5
`

type UpdateTFTRunStateParams struct {
	Status       string
	DesiredState string
	Stage        string
	LastError    *string
	ID           int64
}

func (q *Queries) UpdateTFTRunState(ctx context.Context, arg UpdateTFTRunStateParams) error {
	_, err := q.db.Exec(ctx, updateTFTRunState,
		arg.Status,
		arg.DesiredState,
		arg.Stage,
		arg.LastError,
		arg.ID,
	)
	return err
}

const upsertTFTCheckpoint = `-- name: UpsertTFTCheckpoint :exec
INSERT INTO tft_crawl_checkpoints (
    run_id, stage, scope_key, cursor, processed, next_eligible_at, attempt, updated_at
) VALUES (
    $1, $2, $3, $4, $5, $6, $7, now()
)
ON CONFLICT (run_id, stage, scope_key) DO UPDATE
SET cursor = EXCLUDED.cursor,
    processed = EXCLUDED.processed,
    next_eligible_at = EXCLUDED.next_eligible_at,
    attempt = EXCLUDED.attempt,
    lease_owner = NULL,
    lease_expires_at = NULL,
    updated_at = now()
`

type UpsertTFTCheckpointParams struct {
	RunID          int64
	Stage          string
	ScopeKey       string
	Cursor         []byte
	Processed      int64
	NextEligibleAt pgtype.Timestamptz
	Attempt        int32
}

func (q *Queries) UpsertTFTCheckpoint(ctx context.Context, arg UpsertTFTCheckpointParams) error {
	_, err := q.db.Exec(ctx, upsertTFTCheckpoint,
		arg.RunID,
		arg.Stage,
		arg.ScopeKey,
		arg.Cursor,
		arg.Processed,
		arg.NextEligibleAt,
		arg.Attempt,
	)
	return err
}

